blocks = {}
stop_reason = None
events = []

for ev in client.messages.create(
    model=MODEL,
    max_tokens=300,
    stream=True,
    messages=[{"role": "user", "content": "ChaiCart-কে এক বাক্যে পরিচয় দাও।"}],
):
    events.append(ev.type)
    if ev.type == "content_block_start":
        blocks[ev.index] = {"type": ev.content_block.type, "text": ""}
    elif ev.type == "content_block_delta" and ev.delta.type == "text_delta":
        blocks[ev.index]["text"] += ev.delta.text
    elif ev.type == "message_delta":
        stop_reason = ev.delta.stop_reason
    # ping এবং অচেনা event উপেক্ষা

print("event ক্রম:", events[:3], "...", events[-3:])
print("জোড়া text:", blocks[0]["text"])
print("stop_reason (message_delta থেকে):", stop_reason)
```

**প্রত্যাশিত পর্যবেক্ষণ:** শুরুতে `message_start`, `content_block_start`; শেষে `message_delta`, `message_stop` (মাঝে `ping` থাকতে পারে)। `stop_reason` পেলে `message_delta` থেকে, `message_start`-এ নয়।
